    /// <summary>
    /// Gets the four-letter ISO 15924 code of a script, such as <c>Latn</c>, <c>Arab</c> or <c>Hebr</c>.
    /// </summary>
    /// <remarks>
    /// The code is the first name of the script in <c>PropertyValueAliases.txt</c>: <c>Zinh</c> for
    /// <see cref="ScriptClass.Inherited"/> (<c>Qaai</c> is an alias of it), <c>Zyyy</c> for <see cref="ScriptClass.Common"/>
    /// and <c>Zzzz</c> for <see cref="ScriptClass.Unknown"/>.
    /// </remarks>
    /// <param name="script">The script.</param>
    /// <returns>The ISO 15924 code, with an uppercase first letter and lowercase letters after it.</returns>
    /// <exception cref="ArgumentOutOfRangeException"><paramref name="script"/> is not a defined value.</exception>
    public static string GetIso15924Code(this ScriptClass script)
    {
        if ((uint)script >= (uint)Iso15924Codes.Length)
        {
            throw new ArgumentOutOfRangeException(nameof(script), script, null);
        }

        return Iso15924Codes[(int)script];
    }
